import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import { preview } from 'vite';
import { chromium } from 'playwright';
import { defaultSettings } from '../src/settings-config.js';

const server = await preview({preview:{host:'127.0.0.1',port:0,strictPort:true}});
const browser = await chromium.launch({headless:true});
let release;
let gate=Promise.resolve();
try {
  const page = await browser.newPage({viewport:{width:480,height:760}});
  const errors = [];
  page.on('pageerror', error => errors.push(error.message));
  let sources = ['codex','workbuddy','codebuddy-ide','codeg'].map(source => ({source,kind:source === 'codeg' ? 'webhook' : 'hooks',status:'installed',message:'配置已安装，等待事件',locations:source === 'codex' ? ['/tmp/test-home/.codex/hooks.json','/tmp/test-home/project/.codex/hooks.json'] : ['/tmp/test-home/.codex/hooks.json'],automatic:true,lastEventAt:null}));
  let mutations = 0, fail = false, readFail = false;

  let settings = defaultSettings();
  await page.route('**/api/settings', route => { if(route.request().method()==='PUT') settings=route.request().postDataJSON(); return route.fulfill({json:settings}); });
  await page.route('**/api/integrations', async route => {
    if (route.request().method() === 'POST') {
      mutations++;
      await gate;
      if (fail) return route.fulfill({status:500,json:{error:'配置不可写'}});
      const {source,action} = route.request().postDataJSON();
      sources = sources.map(item => item.source !== source ? item : {...item,automatic:action === 'install',status:action === 'install' ? 'installed' : 'not_installed',message:action === 'install' ? '配置已安装，等待事件' : '已卸载，不会自动安装'});
    }
    if (readFail) return route.fulfill({status:500,json:{error:'接入读取失败'}});
    await route.fulfill({json:{sources}});
  });
  await page.goto(`${server.resolvedUrls.local[0]}desktop-settings.html`);
  await page.locator('[data-integration=codex]').waitFor();
  await page.locator('button[data-style=bot]').click();
  const card = page.locator('[data-integration=codex]');
  assert.equal(await page.locator('.integration-item[data-expanded=true]').count(),0,'details initially collapsed');
  const listening = card.getByRole('switch');
  await listening.click();
  assert.equal(await card.locator('.integration-disclosure').getAttribute('aria-expanded'),'false','switch does not open details');
  await card.locator('.integration-disclosure').click();
  assert.equal(await listening.getAttribute('aria-checked'),'false','disclosure does not toggle listening');
  await page.locator('[data-integration=workbuddy] .integration-disclosure').click();
  assert.equal(await page.locator('.integration-item[data-expanded=true]').count(),1,'only one detail panel opens');
  await card.locator('.integration-disclosure').click();
  assert.match(await card.innerText(),/尚无事件记录/);
  assert.equal(await card.locator('.integration-location-row').count(),2,'all locations are visible without another disclosure');
  assert.equal(await card.getByRole('button',{name:/^打开 .* 所在文件夹$/}).count(),2,'each location has its own open-folder action');
  assert.equal(await card.locator('.integration-detail').count(),0,'installed state is not repeated inside details');
  await card.getByRole('button',{name:/^打开 .* 所在文件夹$/}).first().click();
  await page.getByText(/仅桌面应用支持打开配置文件夹/).waitFor();
  gate = new Promise(resolve => { release = resolve; });
  await card.getByRole('button',{name:'卸载',exact:true}).click();
  assert.equal(mutations,0,'opening confirmation sends no mutation');
  const dialog=page.getByRole('alertdialog');
  assert(await dialog.getByRole('button',{name:'取消'}).evaluate(el=>el===document.activeElement),'cancel receives initial focus');
  await page.keyboard.press('Escape');
  await dialog.waitFor({state:'hidden'});
  await page.waitForFunction(() => document.querySelector('[data-integration=codex] .integration-remove') === document.activeElement);
  assert.equal(mutations,0);
  await card.getByRole('button',{name:'卸载',exact:true}).click();
  await dialog.getByRole('button',{name:'取消'}).click();
  assert.equal(mutations,0,'cancel sends no mutation');
  await card.getByRole('button',{name:'卸载',exact:true}).click();
  await fs.mkdir('artifacts/ui/agent-settings-card',{recursive:true});
  await page.screenshot({path:'artifacts/ui/agent-settings-card/confirmation.png'});
  await dialog.getByRole('button',{name:'确认卸载'}).evaluate(el=>{el.click();el.click();});
  await page.waitForFunction(()=>document.querySelector('[role=alertdialog] button:last-child')?.disabled);
  assert.equal(mutations,1,'duplicate confirmation only sends one request');
  assert(await page.locator('.integration-refresh').isDisabled());
  release();
  await dialog.waitFor({state:'hidden'});
  await card.getByText('未接入',{exact:true}).waitFor();
  assert.equal(await page.locator('button[data-style=bot]').getAttribute('aria-pressed'),'true','saved preference survives');
  assert.match(await page.locator('#save-status').innerText(),/实时生效/);
  // A failed refresh must not leave stale failure badges after a recovery read succeeds.
  readFail = true;
  await page.getByRole('button',{name:'刷新状态'}).click();
  await page.getByText('操作失败：接入读取失败',{exact:true}).waitFor();
  assert.equal(await card.locator('.integration-badge').innerText(),'读取失败');
  readFail = false;
  fail = true;
  await card.getByRole('button',{name:'安装 Hooks'}).click();
  await page.getByText('操作失败：配置不可写',{exact:true}).waitFor();
  assert.equal(await card.locator('.integration-badge').innerText(),'未接入');
  fail = false;
  await card.getByRole('button',{name:'安装 Hooks'}).click();
  await card.getByText('已接入',{exact:true}).waitFor();
  await page.getByRole('button',{name:'刷新状态'}).click();
  await page.getByText('状态已刷新',{exact:true}).waitFor();
  assert.equal(await listening.getAttribute('aria-checked'),'false','refresh preserves listening draft');
  const artifacts = 'artifacts/ui/agent-settings-card';
  await fs.mkdir(artifacts,{recursive:true});
  // A fresh load has no transient action message, matching the initial baseline.
  await page.reload();
  await card.getByText('已接入',{exact:true}).waitFor();
  await page.setViewportSize({width:480,height:1000});
  const compact = await page.locator('.agent-card').boundingBox();
  assert(compact.height >= 235 && compact.height <= 260,'collapsed group stays within height budget');
  const rows = await page.locator('.agent-card .integration-title').evaluateAll(rows=>rows.map(row=>row.getBoundingClientRect().height));
  assert(rows.every(height=>height >= 48 && height <= 52),'all four rows have compact comfortable height');
  await page.screenshot({path:`${artifacts}/after-collapsed.png`,fullPage:true});
  await page.setViewportSize({width:360,height:1000});
  await page.screenshot({path:`${artifacts}/after-collapsed-360.png`,fullPage:true});
  await page.setViewportSize({width:480,height:1000});
  await page.locator('.agent-card').screenshot({path:`${artifacts}/card-collapsed.png`});
  await card.locator('.integration-disclosure').click();
  await page.locator('.agent-card').screenshot({path:`${artifacts}/card-expanded.png`});
  await page.setViewportSize({width:360,height:1000});
  await page.locator('.agent-card').screenshot({path:`${artifacts}/card-expanded-360.png`});
  assert(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth),'two visible paths do not overflow a narrow window');
  await page.setViewportSize({width:480,height:1000});
  sources = sources.map(item=>item.source==='codebuddy-ide'?{...item,status:'partial',message:'配置不完整，请修复 Hooks。'}:item);
  await page.getByRole('button',{name:'刷新状态'}).click();
  await page.getByText('需要修复',{exact:true}).waitFor();
  await page.locator('[data-integration=codebuddy-ide] .integration-disclosure').click();
  await page.locator('.agent-card').screenshot({path:`${artifacts}/card-warning.png`});
  readFail = true;
  await page.reload();
  await page.getByText('读取失败：接入读取失败',{exact:true}).waitFor();
  assert.equal(await page.locator('.agent-card [role=switch]').count(),4,'read failure preserves all four listeners');
  assert(!await listening.isDisabled(),'integration read failure does not disable listening');
  await listening.click();
  await page.locator('.agent-card').screenshot({path:`${artifacts}/card-read-failure.png`});
  readFail = false;
  await page.getByRole('button',{name:'刷新状态'}).click();
  await card.getByText('已接入',{exact:true}).waitFor();
  assert.equal(await listening.getAttribute('aria-checked'),'true','retry preserves latest listener choice');
  for (const width of [360,480]) {
    await page.setViewportSize({width,height:760});
    assert(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth),'no horizontal overflow');
    await page.locator('[data-integration=codeg] .integration-disclosure').click();
    await page.evaluate(()=>scrollTo(0,document.body.scrollHeight));
    const panel = await page.locator('[data-integration=codeg] .integration-content').boundingBox();
    assert(panel.y+panel.height <= 760,'last detail is visible at bottom');
    assert.equal(await page.locator('footer').count(),0);
    await page.screenshot({path:`${artifacts}/after-${width}.png`});
    await page.locator('[data-integration=codeg] .integration-disclosure').click();
  }
  await fs.writeFile(`${artifacts}/after-geometry.json`,JSON.stringify({width:480,cardHeight:compact.height,rowHeights:rows},null,2));
  assert.deepEqual(errors,[]);
  await page.locator('[data-integration=codeg] .integration-disclosure').click();
  await page.locator('[data-integration=codeg]').getByRole('button',{name:'注销',exact:true}).click();
  const before=mutations;
  await page.getByRole('alertdialog').getByRole('button',{name:'取消'}).click();
  assert.equal(mutations,before);
  await page.locator('[data-integration=codeg]').getByRole('button',{name:'注销',exact:true}).click();
  await page.getByRole('alertdialog').getByRole('button',{name:'确认注销'}).click();
  await page.getByRole('alertdialog').waitFor({state:'hidden'});
  assert.equal(mutations,before+1);
  console.log('PASS: status, remove/install, failure/retry, serialization, unsaved changes, narrow geometry');
} catch(error) { console.error(error); throw error; } finally { release?.(); await browser.close(); await server.httpServer.close(); }
